      SUBROUTINE HRPRODLOSS

C***********************************************************************
C
C  FUNCTION: To compute the production and loss rates for EBI species
C
C  PRECONDITIONS: For the SAPRC22_AE65_AQ mechanism
C
C  RETURN VALUES: None
C
C  KEY SUBROUTINES/FUNCTIONS CALLED: None
C
C  REVISION HISTORY: Created by EBI solver program, May 20, 2025
C
C   18 Jul 14 B.Hutzell: revised to use real(8) variables

C***********************************************************************
      USE HRDATA

      IMPLICIT NONE


C.....INCLUDES: NONE


C.....ARGUMENTS: NONE


C.....PARAMETERS: NONE


C.....EXTERNAL FUNCTIONS: NONE


C.....SAVED VARIABLES: NONE
!     CHARACTER( 16 ), SAVE  ::  PNAME = 'HRPRODLOSS'   ! Program name


C.....LOCAL VARIABLES:


C***********************************************************************


      PROD(  HNO3         ) =    2.0000D+00 * RXRAT(    13 )      ! N2O5=0.2000D+01*HNO3
     &                      +    2.0000D+00 * RXRAT(    14 )      ! N2O5=0.2000D+01*HNO3
     &                      +                 RXRAT(    25 )      ! OH+NO2=HNO3
     &                      +                 RXRAT(    31 )      ! HO2+NO=HNO3
     &                      +                 RXRAT(    32 )      ! HO2+NO=HNO3
     &                      +                 RXRAT(   120 )      ! HCHO+NO3=HNO3+HO2+CO
     &                      +                 RXRAT(   126 )      ! GLY+NO3=HNO3+0.1700D+01*CO+...
     &                      +                 RXRAT(   129 )      ! BALD+NO3=HNO3+BZCO3+SumRCO3
     &                      +                 RXRAT(   136 )      ! CATL3+NO3=HNO3+OTHN
     &                      +                 RXRAT(   138 )      ! NAPPRD+NO3=HNO3+OTHN
     &                      +                 RXRAT(   532 )      ! MECHO+NO3=HNO3+MECO3+SumRCO3
     &                      +                 RXRAT(   536 )      ! GLCHO+NO3=HNO3+0.1000D+...
     &                      +                 RXRAT(   541 )      ! ETCHO+NO3=HNO3+R2CO3+SumRCO3
     &                      +    9.4000D-01 * RXRAT(   547 )      ! ACRO+NO3=0.9400D+00*HNO3+...
     &                      +    3.0000D-01 * RXRAT(   559 )      ! MACR+NO3=0.3000D+00*HNO3+...
     &                      +                 RXRAT(   571 )      ! PHEN+NO3=HNO3+BZO
     &                      +                 RXRAT(   636 )      ! RCHO+NO3=HNO3+0.7000D-...
     &                      +    4.0000D-02 * RXRAT(   642 )      ! OLEA1+NO3=0.4000D-01*HNO3+...
     &                      +    2.8000D-01 * RXRAT(   652 )      ! OLEA2+NO3=0.2800D+00*HNO3+...
     &                      +                 RXRAT(   678 )      ! MGLY+NO3=HNO3+MECO3+CO+SumRCO3
     &                      +                 RXRAT(   682 )      ! CRES+NO3=HNO3+BZO
     &                      +                 RXRAT(   684 )      ! XYNL+NO3=HNO3+BZO
     &                      +                 RXRAT(   686 )      ! CATL+NO3=HNO3+BZO
     &                      +    5.0000D-01 * RXRAT(   761 )      ! NO2=0.5000D+00*HNO3+...
     &                      +                 RXRAT(   762 )      ! N2O5=HNO3+H2NO3PIJ
     &                      +                 RXRAT(   763 )      ! N2O5=HNO3+H2NO3PK
     &                      +                 RXRAT(   764 )      ! H2NO3PIJ=HNO3
     &                      +                 RXRAT(   765 )      ! H2NO3PK=HNO3
     &                      +                 RXRAT(   767 )      ! NO3=HNO3
      LOSS(  HNO3         ) =                 RXRAT(    27 )      ! HNO3+OH=NO3
     &                      +                 RXRAT(    28 )      ! HNO3=OH+NO2

      PROD(  HO2H         ) =                 RXRAT(    38 )      ! HO2+HO2=HO2H
     &                      +                 RXRAT(    39 )      ! HO2+HO2=HO2H
      LOSS(  HO2H         ) =                 RXRAT(    42 )      ! HO2H=0.2000D+01*OH
     &                      +                 RXRAT(    43 )      ! HO2H+OH=HO2

      PROD(  CO           ) =                 RXRAT(   117 )      ! HCHO=CO+0.2000D+01*HO2
     &                      +                 RXRAT(   118 )      ! HCHO=CO
     &                      +                 RXRAT(   119 )      ! HCHO+OH=CO+HO2
     &                      +                 RXRAT(   120 )      ! HCHO+NO3=CO+HO2+HNO3
     &                      +    2.0000D+00 * RXRAT(   123 )      ! GLY=0.2000D+01*CO+0.2000D+...
     &                      +                 RXRAT(   124 )      ! GLY=CO+HCHO
     &                      +    1.7000D+00 * RXRAT(   125 )      ! GLY+OH=0.1700D+01*CO+...
     &                      +    1.7000D+00 * RXRAT(   126 )      ! GLY+NO3=0.1700D+01*CO+HNO3+...
     &                      +                 RXRAT(   462 )      ! MACO3+NO=CO+MEO2+HCHO+CO2+...
     &                      +                 RXRAT(   464 )      ! MACO3+NO3=CO+MEO2+HCHO+CO2+...
     &                      +    5.0000D-01 * RXRAT(   465 )      ! MACO3+HO2=0.5000D+00*CO+...
     &                      +    9.0000D-01 * RXRAT(   466 )      ! MACO3+SumRO2=0.9000D+00*CO+...
     &                      +                 RXRAT(   467 )      ! MACO3+SumRCO3=CO+HCHO+CO2+...
     &                      +    3.5000D-01 * RXRAT(   472 )      ! ETHEN+O3=0.3500D+00*CO+...
     &                      +    5.1000D-01 * RXRAT(   474 )      ! ETHEN+O3P=0.5100D+00*CO+...
     &                      +    2.7000D-01 * RXRAT(   476 )      ! ETHEN_OP+NO=0.2700D+00*CO+...
     &                      +    2.2000D-01 * RXRAT(   478 )      ! PROPE+O3=0.2200D+00*CO+...
     &                      +    2.0000D-01 * RXRAT(   480 )      ! PROPE_O3+NO=0.2000D+00*CO+...
     &                      +    3.3000D-01 * RXRAT(   486 )      ! ISOP+O3=0.3300D+00*CO+...
     &                      +    1.4000D-01 * RXRAT(   488 )      ! ISOP_O3+NO=0.1400D+00*CO+...
     &                      +    5.4000D-01 * RXRAT(   496 )      ! BUT13+O3=0.5400D+00*CO+...
     &                      +    3.3000D-01 * RXRAT(   498 )      ! BUT13_O3+NO=0.3300D+00*CO+...
     &                      +    1.7000D-01 * RXRAT(   504 )      ! APINE+O3=0.1700D+00*CO+...
     &                      +    1.7000D-01 * RXRAT(   510 )      ! BPINE+O3=0.1700D+00*CO+...
     &                      +    3.3000D-01 * RXRAT(   513 )      ! ACETL+OH=0.3300D+00*CO+...
     &                      +    3.1000D-01 * RXRAT(   514 )      ! ACETL+O3=0.3100D+00*CO+...
     &                      +    5.0000D-02 * RXRAT(   531 )      ! MECHO_OH+NO=0.5000D-01*CO+...
     &                      +    9.0000D-01 * RXRAT(   533 )      ! MECHO=0.9000D+00*CO+...
     &                      +    9.3000D-01 * RXRAT(   537 )      ! GLCHO=0.9300D+00*CO+...
     &                      +    6.0000D-02 * RXRAT(   539 )      ! GLCHO_HV+NO=0.6000D-01*CO+...
     &                      +    4.0000D-02 * RXRAT(   540 )      ! ETCHO+OH=0.4000D-01*CO+...
     &                      +                 RXRAT(   542 )      ! ETCHO=CO+ETO2+HO2+SumRO2
     &                      +    2.4000D-01 * RXRAT(   543 )      ! ACRO+OH=0.2400D+00*CO+...
     &                      +    3.4000D-01 * RXRAT(   546 )      ! ACRO+O3=0.3400D+00*CO+...
     &                      +    6.0000D-02 * RXRAT(   547 )      ! ACRO+NO3=0.6000D-01*CO+...
     &                      +    1.0600D+00 * RXRAT(   548 )      ! ACRO=0.1060D+01*CO+0.2200D+...
     &                      +    2.1000D-01 * RXRAT(   550 )      ! ACRO_HV+NO=0.2100D+00*CO+...
     &                      +    6.1000D-01 * RXRAT(   557 )      ! MACR_OH+NO=0.6100D+00*CO+...
     &                      +    3.8000D-01 * RXRAT(   558 )      ! MACR+O3=0.3800D+00*CO+...
     &                      +    6.6000D-01 * RXRAT(   561 )      ! MACR_N3+NO=0.6600D+00*CO+...
     &                      +                 RXRAT(   562 )      ! MACR=CO+0.3000D+00*HO2+...
     &                      +    3.6000D-01 * RXRAT(   564 )      ! MVK+O3=0.3600D+00*CO+...
     &                      +    6.0000D-01 * RXRAT(   565 )      ! MVK=0.6000D+00*CO+0.4000D+...
     &                      +    2.0000D-02 * RXRAT(   566 )      ! BUDAL+OH=0.2000D-01*CO+...
     &                      +    4.3000D-01 * RXRAT(   572 )      ! ALK1+OH=0.4300D+00*CO+...
     &                      +    5.0000D-02 * RXRAT(   574 )      ! ALK3+OH=0.5000D-01*CO+...
     &                      +    3.7000D-01 * RXRAT(   583 )      ! OLE1+O3=0.3700D+00*CO+...
     &                      +    1.8000D-01 * RXRAT(   587 )      ! OLE2+O3=0.1800D+00*CO+...
     &                      +    2.9000D-01 * RXRAT(   589 )      ! OLE2_O3+NO=0.2900D+00*CO+...
     &                      +    1.7000D-01 * RXRAT(   593 )      ! OLE3+O3=0.1700D+00*CO+...
     &                      +    7.0000D-02 * RXRAT(   597 )      ! OLE4+O3=0.7000D-01*CO+...
     &                      +    1.8000D-01 * RXRAT(   599 )      ! OLE4_O3+NO=0.1800D+00*CO+...
     &                      +    1.2000D-01 * RXRAT(   605 )      ! TERP+O3=0.1200D+00*CO+...
     &                      +    1.0000D-02 * RXRAT(   610 )      ! TERP_N3+NO=0.1000D-01*CO+...
     &                      +    4.0000D-02 * RXRAT(   617 )      ! SESQ_O3+NO=0.4000D-01*CO+...
     &                      +    8.0000D-02 * RXRAT(   627 )      ! FURNS+OH=0.8000D-01*CO+...
     &                      +    7.9000D-01 * RXRAT(   628 )      ! FURNS+O3=0.7900D+00*CO+...
     &                      +    2.8000D-01 * RXRAT(   629 )      ! FURNS+NO3=0.2800D+00*CO+...
     &                      +    2.2000D-01 * RXRAT(   631 )      ! STYRS+O3=0.2200D+00*CO+...
     &                      +    2.0000D-02 * RXRAT(   635 )      ! RCHO+OH=0.2000D-01*CO+...
     &                      +                 RXRAT(   637 )      ! RCHO=CO+0.5100D+00*xHO2+...
     &                      +    4.0000D-02 * RXRAT(   640 )      ! OLEA1_OH+NO=0.4000D-01*CO+...
     &                      +    1.1000D-01 * RXRAT(   641 )      ! OLEA1+O3=0.1100D+00*CO+...
