     &                      +    9.0000D-02 * RXRAT(   646 )      ! OLEA2+OH=0.9000D-01*CO+...
     &                      +    2.0000D-02 * RXRAT(   648 )      ! OLEA2_OH+NO=0.2000D-01*CO+...
     &                      +    2.9000D-01 * RXRAT(   649 )      ! OLEA2+O3=0.2900D+00*CO+...
     &                      +    8.0000D-02 * RXRAT(   651 )      ! OLEA2_O3+NO=0.8000D-01*CO+...
     &                      +    3.0000D-02 * RXRAT(   652 )      ! OLEA2+NO3=0.3000D-01*CO+...
     &                      +    7.0000D-02 * RXRAT(   654 )      ! OLEA2_N3+NO=0.7000D-01*CO+...
     &                      +    1.1100D+00 * RXRAT(   655 )      ! OLEA2=0.1110D+01*CO+...
     &                      +    9.0000D-02 * RXRAT(   659 )      ! KET2=0.9000D-01*CO+0.3000D+...
     &                      +    1.0000D-02 * RXRAT(   662 )      ! LVKS_OH+NO=0.1000D-01*CO+...
     &                      +    3.0000D-01 * RXRAT(   663 )      ! LVKS+O3=0.3000D+00*CO+...
     &                      +    2.0000D-02 * RXRAT(   665 )      ! LVKS_O3+NO=0.2000D-01*CO+...
     &                      +    6.0000D-01 * RXRAT(   666 )      ! LVKS=0.6000D+00*CO+0.1400D+...
     &                      +    4.0000D-02 * RXRAT(   669 )      ! OLEP_OH+NO=0.4000D-01*CO+...
     &                      +    1.8000D-01 * RXRAT(   670 )      ! OLEP+O3=0.1800D+00*CO+...
     &                      +                 RXRAT(   677 )      ! MGLY+OH=CO+0.1000D-01*RO2C+...
     &                      +                 RXRAT(   678 )      ! MGLY+NO3=CO+MECO3+HNO3+SumRCO3
     &                      +                 RXRAT(   679 )      ! MGLY=CO+MECO3+HO2+SumRCO3
     &                      +    1.0000D-02 * RXRAT(   687 )      ! RCNO3+OH=0.1000D-01*CO+...
     &                      +    3.4000D-01 * RXRAT(   690 )      ! RCNO3=0.3400D+00*CO+...
     &                      +    2.0000D-02 * RXRAT(   692 )      ! RCNO3_HV+NO=0.2000D-01*CO+...
     &                      +    1.0000D-02 * RXRAT(   703 )      ! RDNO3+OH=0.1000D-01*CO+...
     &                      +    1.0000D-02 * RXRAT(   709 )      ! R2NO3+OH=0.1000D-01*CO+...
     &                      +    1.0000D-02 * RXRAT(   710 )      ! R2NO3=0.1000D-01*CO+NO2+...
     &                      +    1.0000D-02 * RXRAT(   712 )      ! R2NO3_HV+NO=0.1000D-01*CO+...
     &                      +    4.0000D-02 * RXRAT(   721 )      ! HPCRB_OH+NO=0.4000D-01*CO+...
     &                      +    1.0000D-02 * RXRAT(   727 )      ! AFG1+OH=0.1000D-01*CO+...
     &                      +    3.0000D-02 * RXRAT(   730 )      ! AFG1=0.3000D-01*CO+0.3000D+...
     &                      +    3.0000D-02 * RXRAT(   733 )      ! AFG2A+OH=0.3000D-01*CO+...
     &                      +    3.0000D-02 * RXRAT(   740 )      ! AFG2B=0.3000D-01*CO+...
     &                      +    5.0000D-01 * RXRAT(   745 )      ! PAN2+OH=0.5000D+00*CO+...
     &                      +    3.1000D-01 * RXRAT(   749 )      ! APANS+O3=0.3100D+00*CO+...
     &                      +    4.0000D-01 * RXRAT(   751 )      ! APANS=0.4000D+00*CO+...
      LOSS(  CO           ) =                 RXRAT(    45 )      ! CO+OH=HO2+CO2

      PROD(  CO2          ) =                 RXRAT(    45 )      ! CO+OH=CO2+HO2
     &                      +                 RXRAT(    82 )      ! MECO3+NO=CO2+MEO2+NO2+SumRO2
     &                      +                 RXRAT(    84 )      ! MECO3+NO3=CO2+MEO2+NO2+SumRO2
     &                      +    5.0000D-01 * RXRAT(    85 )      ! MECO3+HO2=0.5000D+00*CO2+...
     &                      +    9.0000D-01 * RXRAT(    86 )      ! MECO3+SumRO2=0.9000D+...
     &                      +                 RXRAT(    87 )      ! MECO3+SumRCO3=CO2+MEO2+SumRO2
     &                      +                 RXRAT(    89 )      ! BZCO3+NO=CO2+NO2+BZO2+SumRO2
     &                      +    5.0000D-01 * RXRAT(    90 )      ! BZCO3+HO2=0.5000D+00*CO2+...
     &                      +                 RXRAT(    91 )      ! BZCO3+NO3=CO2+NO2+BZO2+SumRO2
     &                      +                 RXRAT(    92 )      ! BZCO3+SumRO2=CO2+BZO2+...
     &                      +                 RXRAT(    93 )      ! BZCO3+SumRCO3=CO2+SumRCO3+...
     &                      +    4.0000D-01 * RXRAT(   122 )      ! PAN=0.4000D+00*CO2+0.4000D+...
     &                      +    3.0000D-01 * RXRAT(   125 )      ! GLY+OH=0.3000D+00*CO2+...
     &                      +    3.0000D-01 * RXRAT(   126 )      ! GLY+NO3=0.3000D+00*CO2+...
     &                      +    4.0000D-01 * RXRAT(   131 )      ! PBZN=0.4000D+00*CO2+...
     &                      +                 RXRAT(   455 )      ! R2CO3+NO=CO2+0.9500D+...
     &                      +                 RXRAT(   457 )      ! R2CO3+NO3=CO2+0.9500D+...
     &                      +    5.0000D-01 * RXRAT(   458 )      ! R2CO3+HO2=0.5000D+00*CO2+...
     &                      +    9.0000D-01 * RXRAT(   459 )      ! R2CO3+SumRO2=0.9000D+...
     &                      +                 RXRAT(   460 )      ! R2CO3+SumRCO3=CO2+0.9600D+...
     &                      +                 RXRAT(   462 )      ! MACO3+NO=CO2+MEO2+HCHO+NO2+...
     &                      +                 RXRAT(   464 )      ! MACO3+NO3=CO2+MEO2+HCHO+...
     &                      +    5.0000D-01 * RXRAT(   465 )      ! MACO3+HO2=0.5000D+00*CO2+...
     &                      +    9.0000D-01 * RXRAT(   466 )      ! MACO3+SumRO2=0.9000D+...
     &                      +                 RXRAT(   467 )      ! MACO3+SumRCO3=CO2+HCHO+...
     &                      +    2.3000D-01 * RXRAT(   472 )      ! ETHEN+O3=0.2300D+00*CO2+...
     &                      +    7.0000D-02 * RXRAT(   475 )      ! ETHEN_OP=0.7000D-01*CO2+...
     &                      +    2.4000D-01 * RXRAT(   478 )      ! PROPE+O3=0.2400D+00*CO2+...
     &                      +    5.0000D-02 * RXRAT(   479 )      ! PROPE_O3=0.5000D-01*CO2+...
     &                      +    1.3000D-01 * RXRAT(   486 )      ! ISOP+O3=0.1300D+00*CO2+...
     &                      +    4.0000D-02 * RXRAT(   487 )      ! ISOP_O3=0.4000D-01*CO2+...
     &                      +    1.2000D-01 * RXRAT(   496 )      ! BUT13+O3=0.1200D+00*CO2+...
     &                      +    9.0000D-02 * RXRAT(   497 )      ! BUT13_O3=0.9000D-01*CO2+...
     &                      +    3.0000D-02 * RXRAT(   504 )      ! APINE+O3=0.3000D-01*CO2+...
     &                      +    1.0000D-02 * RXRAT(   508 )      ! BPINE_OH=0.1000D-01*CO2+...
     &                      +    1.2000D-01 * RXRAT(   510 )      ! BPINE+O3=0.1200D+00*CO2+...
     &                      +    4.0000D-02 * RXRAT(   511 )      ! BPINE+NO3=0.4000D-01*CO2+...
     &                      +    4.7000D-01 * RXRAT(   514 )      ! ACETL+O3=0.4700D+00*CO2+...
     &                      +                 RXRAT(   526 )      ! HCOOH+OH=CO2+HO2
     &                      +    1.0000D-02 * RXRAT(   530 )      ! MECHO_OH=0.1000D-01*CO2+...
     &                      +    2.0000D-02 * RXRAT(   538 )      ! GLCHO_HV=0.2000D-01*CO2+...
     &                      +    2.6000D-01 * RXRAT(   546 )      ! ACRO+O3=0.2600D+00*CO2+...
     &                      +    1.6000D-01 * RXRAT(   548 )      ! ACRO=0.1600D+00*CO2+...
